"""
一所学校里有一些班级，每个班级里有一些学生，现在每个班都会进行一场期末考试。给你一个二维数组 classes，其中classes[i] = [passi, totali]，表示你提前知道了第i个班级总共有totali个学生，其中只有passi个学生可以通过考试。
给你一个整数extraStudents，表示额外有extraStudents个聪明的学生，他们 一定能通过任何班级的期末考。你需要给这extraStudents个学生每人都安排一个班级，使得 所有班级的 平均通过率 最大。
一个班级的通过率等于这个班级通过考试的学生人数除以这个班级的总人数。平均通过率是所有班级的通过率之和除以班级数目。
请你返回在安排这 extraStudents 个学生去对应班级后的 最大平均通过率。与标准答案误差范围在10-5以内的结果都会视为正确结果。

示例 1：
输入：classes = [[1,2],[3,5],[2,2]], extraStudents = 2
输出：0.78333
解释：你可以将额外的两个学生都安排到第一个班级，平均通过率为 (3/4 + 3/5 + 2/2) / 3 = 0.78333 。

示例 2：
输入：classes = [[2,4],[3,9],[4,5],[2,10]], extraStudents = 4
输出：0.53485

来源：力扣（LeetCode）
链接：https://leetcode.cn/problems/maximum-average-pass-ratio
"""

"""
class Solution:
    def maxAverageRatio(self, classes: List[List[int]], extraStudents: int) -> float:
        h = [(a / b - (a + 1) / (b + 1), a, b) for a, b in classes]
        heapify(h)
        for _ in range(extraStudents):
            _, a, b = heappop(h)
            a, b = a + 1, b + 1
            heappush(h, (a / b - (a + 1) / (b + 1), a, b))
        return sum(v[1] / v[2] for v in h) / len(classes)

作者：lcbin
链接：https://leetcode.cn/problems/maximum-average-pass-ratio/solution/python3javacgo-yi-ti-yi-jie-you-xian-dui-qrmo/
来源：力扣（LeetCode）
"""
from heapq import heapify, heappush, heappop

class Solution:
    def add(self, new_q, quene):
        if not quene:
            return [new_q]
        l, r = 0, len(quene) - 1
        mid = (l + r) // 2
        score = new_q[2]
        while l < r-1 and quene[l][-1] >= score >= quene[r][-1]:
            if score == quene[mid][-1]:
                break
            if score > quene[mid][-1]:
                r = mid
            else:
                l = mid
            mid = (l + r) // 2

        if quene[l][-1] >= score >= quene[r][-1]:
            mid = l+1
        elif quene[r][-1] > score:
            mid = r+1
        elif quene[l][-1] < score:
            mid = l
        quene = quene[:mid] + [new_q] + quene[mid:]
        return quene

    def maxAverageRatio(self, classes, extraStudents: int) -> float:
        # quene = []
        # for c in classes:
        #     score = (c[0] + 1) / (c[1] + 1) - c[0] / c[1]
        #     quene = self.add(c + [score], quene)
        # for _ in range(extraStudents):
        #     score = (quene[0][0]+2) / (quene[0][1]+2) - (quene[0][0]+1) / (quene[0][1]+1)
        #     new_q = [quene[0][0]+1, quene[0][1]+1, score]
        #     quene = self.add(new_q, quene[1:])
        # res = 0
        # for q in quene:
        #     res += q[0] / q[1]
        # res /= len(classes)
        # return res
        h = [(a / b - (a + 1) / (b + 1), a, b) for a, b in classes]
        heapify(h)
        for _ in range(extraStudents):
            _, a, b = heappop(h)
            a, b = a + 1, b + 1
            heappush(h, (a / b - (a + 1) / (b + 1), a, b))
        return sum(v[1] / v[2] for v in h) / len(classes)


